import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"पहले अवलोकन, फिर सीमित हस्तक्षेप के मानदंड","description":"","frontmatter":{},"headers":[],"relativePath":"hi/0083-先观测后有限干涉准则.md","filePath":"hi/0083-先观测后有限干涉准则.md"}'),i={name:"hi/0083-先观测后有限干涉准则.md"};function h(o,t,l,n,_,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="पहले-अवलोकन-फिर-सीमित-हस्तक्षेप-के-मानदंड" tabindex="-1">पहले अवलोकन, फिर सीमित हस्तक्षेप के मानदंड <a class="header-anchor" href="#पहले-अवलोकन-फिर-सीमित-हस्तक्षेप-के-मानदंड" aria-label="Permalink to &quot;पहले अवलोकन, फिर सीमित हस्तक्षेप के मानदंड&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>83</td></tr><tr><td>मॉड्यूल</td><td>अंतर-पटल अंतःक्रिया और समय-नियम</td></tr><tr><td>कीवर्ड</td><td>पहले अवलोकन, सीमित हस्तक्षेप, अवलोकन-प्रोटोकॉल, हस्तक्षेप-सीमा, कारण-मूल्यांकन</td></tr></tbody></table><h2 id="i-मानदंडों-की-केंद्रीय-अवधारणा" tabindex="-1">I. मानदंडों की केंद्रीय अवधारणा <a class="header-anchor" href="#i-मानदंडों-की-केंद्रीय-अवधारणा" aria-label="Permalink to &quot;I. मानदंडों की केंद्रीय अवधारणा&quot;">​</a></h2><p>«पहले अवलोकन, फिर सीमित हस्तक्षेप» हेंग-ब्रह्मांड की समय-प्रत्यावर्तन और अंतर-पटल पुरातत्व संचालनों का सर्वप्रमुख मानदंड है, जिसकी केंद्रीय अवधारणा सोलह अक्षरों में संक्षेपित की जा सकती है: «देखो बिना स्पर्श, मापो बिना क्षोभ, सोच-समझकर आगे बढ़ो, सीमा में रहकर करो।» इस मानदंड की स्थापना ब्रह्मांड के कारण-नियमों के प्रति गहन श्रद्धा पर आधारित है — अतीत या अन्य पटल में कोई भी प्रत्यक्ष हस्तक्षेप अप्रत्याशित कारण-शृंखला प्रतिक्रियाएँ उत्पन्न कर सकता है, और पर्याप्त पूर्व-अवलोकन ही जोखिम को न्यूनतम करने का एकमात्र विश्वसनीय साधन है।</p><p>मानदंड का दार्शनिक आधार «संज्ञानात्मक विनम्रता» सिद्धांत है। हेंग-ब्रह्मांड स्वीकार करता है कि पटल-परम शक्ति भी किसी समय-नोड या पटल-सभ्यता की सम्पूर्ण कारण-संबंधों को पूर्ण रूप से नहीं जान सकती। अतः किसी भी हस्तक्षेप-कार्य से पहले सबसे सतर्क दृष्टिकोण से समग्र अवलोकन किया जाना चाहिए, लक्ष्य-वस्तु की कारण-संरचना और विकास-प्रवृत्तियों को यथासंभव पूर्ण रूप से समझना चाहिए। केवल पर्याप्त अवलोकन-आँकड़ों और स्पष्ट जोखिम-मूल्यांकन की पूर्व-शर्त पर ही सीमित हस्तक्षेप की अनुमति है।</p><p>«पहले अवलोकन, फिर सीमित हस्तक्षेप» दो स्वतंत्र चरण नहीं, बल्कि एक जैविक संचालन-चक्र है: अवलोकन हस्तक्षेप को आधार देता है, हस्तक्षेप के परिणाम पुनः नए अवलोकन-आँकड़ों के रूप में प्रतिपुष्ट होते हैं, और दोनों चक्राकार रूप से आगे बढ़ते हैं। यह चक्र सुनिश्चित करता है कि प्रत्येक हस्तक्षेप नवीनतम और सबसे पूर्ण संज्ञानात्मक आधार पर निर्मित हो।</p><h2 id="ii-अवलोकन-चरण-की-संचालन-विधियाँ" tabindex="-1">II. अवलोकन-चरण की संचालन-विधियाँ <a class="header-anchor" href="#ii-अवलोकन-चरण-की-संचालन-विधियाँ" aria-label="Permalink to &quot;II. अवलोकन-चरण की संचालन-विधियाँ&quot;">​</a></h2><p>अवलोकन-चरण सम्पूर्ण संचालन-प्रवाह की नींव है, और इसकी गुणवत्ता सीधे बाद के हस्तक्षेप की सुरक्षा और प्रभावशीलता निर्धारित करती है। अवलोकन-चरण को निम्न संचालन-विधियों का पालन करना चाहिए:</p><h3 id="_2-1-अवलोकन-अवधि-आवश्यकताएँ" tabindex="-1">2.1 अवलोकन-अवधि आवश्यकताएँ <a class="header-anchor" href="#_2-1-अवलोकन-अवधि-आवश्यकताएँ" aria-label="Permalink to &quot;2.1 अवलोकन-अवधि आवश्यकताएँ&quot;">​</a></h3><p>अवलोकन-अवधि लक्ष्य-काल की कुल लंबाई के 1% से कम नहीं होनी चाहिए, और निरपेक्ष अवधि अपने पटल के मानक-समय के 72 घंटों से कम नहीं होनी चाहिए। उदाहरणार्थ, 100 वर्ष की अवधि के ऐतिहासिक-काल के प्रत्यावर्तन-अवलोकन हेतु शुद्ध अवलोकन-चरण 1 वर्ष से कम नहीं; 10 वर्ष की अवधि के काल के अवलोकन हेतु शुद्ध अवलोकन-चरण 72 घंटों से कम नहीं। यह न्यूनतम अवधि-आवश्यकता सुनिश्चित करती है कि अवलोकनकर्ता लक्ष्य-काल की आवर्तक-परिवर्तनों और दीर्घकालीन-प्रवृत्तियों को पकड़ सके, अत्यधिक छोटे अवलोकन-खिड़की से उत्पन्न एकांगी-निर्णयों से बच सके।</p><h3 id="_2-2-अवलोकन-आयाम-आवश्यकताएँ" tabindex="-1">2.2 अवलोकन-आयाम आवश्यकताएँ <a class="header-anchor" href="#_2-2-अवलोकन-आयाम-आवश्यकताएँ" aria-label="Permalink to &quot;2.2 अवलोकन-आयाम आवश्यकताएँ&quot;">​</a></h3><p>अवलोकन को निम्न पाँच आयामों को आच्छादित करना चाहिए, एक भी छूटे नहीं:</p><table tabindex="0"><thead><tr><th>अवलोकन-आयाम</th><th>विशिष्ट सामग्री</th><th>अवलोकन-विधि</th></tr></thead><tbody><tr><td>भौतिक-आयाम</td><td>भौगोलिक-पर्यावरण, पारिस्थितिकी-तंत्र, बुनियादी-सुविधाएँ, भौतिक-संसाधन वितरण</td><td>स्थान-स्कैनिंग, पदार्थ-विश्लेषण</td></tr><tr><td>ऊर्जा-आयाम</td><td>ऊर्जा-घनत्व वितरण, नियम-प्राचल, ऊर्जा-प्रवाह प्रतिमान</td><td>ऊर्जा-स्पेक्ट्रम विश्लेषण, नियम-संसूचन</td></tr><tr><td>जीवन-आयाम</td><td>प्रजाति-वितरण, जनसंख्या-संख्या, स्वास्थ्य-स्थिति, विकास-स्तर</td><td>जीवन-संकेत स्कैनिंग, आनुवंशिक-नमूनाकरण</td></tr><tr><td>चेतना-आयाम</td><td>सभ्यता-रूप, सामाजिक-संरचना, विचार-धारणाएँ, सामूहिक-चेतना प्रवृत्तियाँ</td><td>चेतना-क्षेत्र निष्क्रिय-श्रवण, सांस्कृतिक-विश्लेषण</td></tr><tr><td>कारण-आयाम</td><td>प्रमुख कारण-शृंखलाएँ, ऐतिहासिक-नोड, विकास-प्रवृत्तियाँ, संभावित जोखिम</td><td>कारण-शृंखला अनुरेखण, प्रवृत्ति-अनुमान</td></tr></tbody></table><h3 id="_2-3-अवलोकन-तटस्थता-आवश्यकताएँ" tabindex="-1">2.3 अवलोकन-तटस्थता आवश्यकताएँ <a class="header-anchor" href="#_2-3-अवलोकन-तटस्थता-आवश्यकताएँ" aria-label="Permalink to &quot;2.3 अवलोकन-तटस्थता आवश्यकताएँ&quot;">​</a></h3><p>अवलोकन-चरण को कड़ाई से तटस्थता बनाए रखनी चाहिए; अवलोकनकर्ता किसी भी रूप में अवलोकन-वस्तु को प्रभावित नहीं करेंगे। विशेष रूप से वर्जित व्यवहार: अवलोकन-वस्तु के साथ किसी भी रूप का संवाद, अवलोकन-क्षेत्र में कोई भौतिक या ऊर्जा-चिह्न छोड़ना, अवलोकन-वस्तु के व्यवहार का मार्गदर्शन या संकेत, और चेतना-क्षेत्र में बोधगम्य कोई विचार-तरंग छोड़ना।</p><p>अवलोकन-चरण में अवलोकनकर्ता की अस्तित्व-स्थिति «शुद्ध निष्क्रिय-बोध» होनी चाहिए, अर्थात केवल सूचना ग्रहण करना, कोई सूचना उत्सर्जित नहीं करना। लंगर-आधारन उपकरण अवलोकनकर्ता के लिए «अवलोकन-परिरक्षण क्षेत्र» की एक परत निर्मित करेगा, यह सुनिश्चित करते हुए कि अवलोकनकर्ता का अस्तित्व अवलोकन-वस्तु को बोधगम्य न हो, और अवलोकनकर्ता अनजाने में हस्तक्षेप-संकेत उत्सर्जित न करे।</p><h2 id="iii-सीमित-हस्तक्षेप-की-परिभाषा-और-सीमा" tabindex="-1">III. सीमित हस्तक्षेप की परिभाषा और सीमा <a class="header-anchor" href="#iii-सीमित-हस्तक्षेप-की-परिभाषा-और-सीमा" aria-label="Permalink to &quot;III. सीमित हस्तक्षेप की परिभाषा और सीमा&quot;">​</a></h2><p>अवलोकन-चरण पूर्ण होने के बाद संचालन-दल को «अवलोकन-रिपोर्ट और हस्तक्षेप-व्यवहार्यता मूल्यांकन» प्रस्तुत करना होगा, और समय-नियम समिति या पटल प्रशासन के अनुमोदन के बाद ही सीमित हस्तक्षेप-चरण में प्रवेश कर सकता है। «सीमित हस्तक्षेप» की «सीमितता» निम्न तीन स्तरों में प्रकट होती है:</p><h3 id="_3-1-क्षेत्र-सीमित" tabindex="-1">3.1 क्षेत्र-सीमित <a class="header-anchor" href="#_3-1-क्षेत्र-सीमित" aria-label="Permalink to &quot;3.1 क्षेत्र-सीमित&quot;">​</a></h3><p>हस्तक्षेप-व्यवहार कड़ाई से अनुमोदन-पत्र में निर्धारित «हस्तक्षेप-अनुमति क्षेत्र» तक सीमित होना चाहिए, जो सामान्यतः अवलोकन-क्षेत्र के कुल क्षेत्रफल के 1% से अधिक नहीं होता। अनुमति-क्षेत्र से बाहर का कोई भी हस्तक्षेप-व्यवहार उल्लंघन माना जाता है, और संचालक कानूनी उत्तरदायित्व वहन करेगा।</p><h3 id="_3-2-मात्रा-सीमित" tabindex="-1">3.2 मात्रा-सीमित <a class="header-anchor" href="#_3-2-मात्रा-सीमित" aria-label="Permalink to &quot;3.2 मात्रा-सीमित&quot;">​</a></h3><p>हस्तक्षेप का ऊर्जा-उत्सर्जन और सूचना-इंजेक्शन «हस्तक्षेप-सीमा» से अधिक नहीं होना चाहिए। हस्तक्षेप-सीमा लक्ष्य-वस्तु की कारण-संवेदनशीलता के अनुसार गतिशील रूप से निर्धारित होती है, गणना-सूत्र: हस्तक्षेप-सीमा = लक्ष्य-क्षेत्र की कुल ऊर्जा × कारण-संवेदनशीलता गुणांक × 0.0001। कारण-संवेदनशीलता गुणांक की सीमा 0.1 से 10; सभ्यता-स्तर जितना ऊँचा, ऐतिहासिक-नोड जितना महत्वपूर्ण, गुणांक उतना बड़ा। इसका अर्थ है कि महत्वपूर्ण ऐतिहासिक-नोडों के लिए हस्तक्षेप-सीमा अत्यंत निम्न है, और लगभग कोई ठोस ऊर्जा-इंजेक्शन अनुमत नहीं।</p><h3 id="_3-3-समय-सीमित" tabindex="-1">3.3 समय-सीमित <a class="header-anchor" href="#_3-3-समय-सीमित" aria-label="Permalink to &quot;3.3 समय-सीमित&quot;">​</a></h3><p>हस्तक्षेप-व्यवहार की अवधि अवलोकन-चरण की कुल अवधि के 10% से अधिक नहीं होनी चाहिए, और निरपेक्ष अवधि अपने पटल के मानक-समय के 24 घंटों से अधिक नहीं। हस्तक्षेप समाप्ति के बाद संचालक को तुरंत लक्ष्य-काल या लक्ष्य-पटल से पीछे हटना होगा, ठहरना नहीं।</p><h2 id="iv-हस्तक्षेप-के-बाद-कारण-मूल्यांकन-और-सुधार" tabindex="-1">IV. हस्तक्षेप के बाद कारण-मूल्यांकन और सुधार <a class="header-anchor" href="#iv-हस्तक्षेप-के-बाद-कारण-मूल्यांकन-और-सुधार" aria-label="Permalink to &quot;IV. हस्तक्षेप के बाद कारण-मूल्यांकन और सुधार&quot;">​</a></h2><p>सीमित हस्तक्षेप समाप्त होने के बाद संचालन-दल को तुरंत «हस्तक्षेपोत्तर कारण-मूल्यांकन» करना होगा, लंगर नेटवर्क द्वारा हस्तक्षेप-व्यवहार से उत्पन्न कारण-शृंखला परिवर्तनों की निगरानी करना। मूल्यांकन-सामग्री: कारण-विचलन का परिमाण, विचलन की प्रसार-सीमा, विचलन की दीर्घकालिक विकास-प्रवृत्ति, और विरोधाभास-जोखिम की उपस्थिति।</p><p>यदि मूल्यांकन में पाया जाए कि कारण-विचलन स्वीकार्य सीमा से अधिक है (विचलन-परिमाण लक्ष्य-क्षेत्र की कुल कारण-राशि के 0.01% से अधिक), संचालन-दल को तुरंत «कारण-सुधार प्रक्रिया» प्रारंभ करनी होगी। कारण-सुधार के तरीके: बाद के समय-नोडों पर प्रतिपूरक-सूचना इंजेक्ट करना, लंगर नेटवर्क द्वारा कारण-शृंखला सूक्ष्म-समायोजन, और अति-स्थिति में पूर्व हस्तक्षेप के प्रभाव को समाप्त करने हेतु द्वितीयक प्रत्यावर्तन।</p><p>सभी हस्तक्षेप-व्यवहार और उनके कारण-मूल्यांकन परिणाम «समय-संचालन अभिलेखागार» में दर्ज होने चाहिए, स्थायी रूप से संरक्षित, आगामी लेखापरीक्षा और अनुसंधान हेतु।</p><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p>पहले अवलोकन, फिर सीमित हस्तक्षेप के मानदंड हेंग-ब्रह्मांड की समय और पटल-संचालन क्षेत्र में बुद्धि का सार हैं। पर्याप्त अवलोकन को पूर्व-शर्त, कड़ी सीमाओं को सीमांत और पश्चात-मूल्यांकन को गारंटी बनाकर, यह «जानकर करो, सीमा में रहकर करो» की संचालन-प्रतिमान रचता है। इस मानदंड का मूल उद्देश्य अन्वेषण के हाथ बाँधना नहीं, बल्कि यह सुनिश्चित करना है कि प्रत्येक अन्वेषण ब्रह्मांड के कारण-व्यवस्था को नष्ट करने की कीमत पर न हो।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>82-时间回溯基本原则 (समय-प्रत्यावर्तन के मूल सिद्धांत)</li><li>84-考古协议总纲 (पुरातत्व-प्रोटोकॉल सामान्य-रूपरेखा)</li><li>89-时间悖论防控机制 (समय-विरोधाभास रोकथाम-नियंत्रण तंत्र)</li></ul>',32)])])}const b=a(i,[["render",h]]);export{c as __pageData,b as default};
